    settings: { kind: "json", path: h(".claude/settings.json"), mcpKey: "mcpServers", hooksKey: "hooks" },
    commandsDir: h(".claude/commands"),
    agentsDir: h(".claude/agents"),
    note: "Full surface: skills + MCP + hooks + commands + agents + env.",
  },
  codex: {
    label: "Codex CLI/app",
    skillsDir: h(".codex/skills"),
    settings: { kind: "toml", path: h(".codex/config.toml") },
    hooksFile: { kind: "json", path: h(".codex/hooks.json") },
    commandsDir: null, // commands ship via plugins, not a bare dir
    agentsDir: h(".codex/agents"),
    note: "Skills + MCP + hooks + plugins + native memories/goals/websearch.",
  },
  claudeDesktop: {
    label: "Claude Desktop",
    skillsDir: null, // NO skills dir — hard architectural limit
    settings: {
      kind: "json",
      path: h("Library/Application Support/Claude/claude_desktop_config.json"),
      mcpKey: "mcpServers",
    },
    commandsDir: null,
    agentsDir: null,
    note: "MCP servers are the ONLY extensibility surface. No skills/hooks/commands.",
  },
};

// ---- helpers --------------------------------------------------------------
function listSkillDirs(dir) {
  if (!dir || !fs.existsSync(dir)) return null;
  const out = new Set();
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith(".")) continue;
    const full = path.join(dir, entry.name);
    let isDir = entry.isDirectory();
    if (entry.isSymbolicLink()) {
      try {
        isDir = fs.statSync(full).isDirectory();
      } catch {
        isDir = false; // dangling symlink
      }
    }
    if (isDir) out.add(entry.name);
  }
  return out;
}

function danglingSymlinks(dir) {
  if (!dir || !fs.existsSync(dir)) return [];
  const bad = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isSymbolicLink()) continue;
    const full = path.join(dir, entry.name);
    try {
      fs.statSync(full);
    } catch {
      bad.push(entry.name);
    }
  }
  return bad;
}

function readJson(p) {
  try {
    return JSON.parse(fs.readFileSync(p, "utf8"));
  } catch {
    return null;
  }
}

// Light TOML probe — enough to count top-level [mcp_servers.<name>] tables and
// [features] booleans without a TOML dependency. Not a full parser.
function probeToml(p) {
  let text;
  try {
    text = fs.readFileSync(p, "utf8");
  } catch {
    return null;
  }
  const mcp = new Set();
  for (const m of text.matchAll(/^\[mcp_servers\.([A-Za-z0-9_-]+)\]\s*$/gm)) {
    mcp.add(m[1]);
  }
  const features = {};
  const featSection = text.match(/^\[features\]([\s\S]*?)(?=^\[)/m);
  if (featSection) {
    for (const m of featSection[1].matchAll(/^([A-Za-z0-9_]+)\s*=\s*(true|false)/gm)) {
      features[m[1]] = m[2] === "true";
    }
  }
  return { mcp: [...mcp].sort(), features };
}

function countDir(dir, ext) {
  if (!dir || !fs.existsSync(dir)) return null;
  return fs
    .readdirSync(dir)
    .filter((f) => !f.startsWith(".") && (!ext || f.endsWith(ext))).length;
}

// ---- scan -----------------------------------------------------------------
const canonical = listSkillDirs(CANONICAL_SKILLS);
if (!canonical) {
  console.error(`FATAL: canonical skills SoT not found at ${CANONICAL_SKILLS}`);
  process.exit(2);
}

const report = {
  schemaVersion: 1,
  source: "harness-parity-scan",
  safety: { modelCalls: false, apiCalls: false, mutates: false },
  canonicalSkills: { path: CANONICAL_SKILLS, count: canonical.size },
  harnesses: {},
};

for (const [key, def] of Object.entries(HARNESSES)) {
  const entry = { label: def.label, note: def.note, surfaces: {} };

  // --- skills surface ---
  if (def.skillsDir) {
    const present = listSkillDirs(def.skillsDir);
    if (present) {
      const missing = [...canonical].filter((s) => !present.has(s)).sort();
      const extra = [...present].filter((s) => !canonical.has(s)).sort();
      const covered = canonical.size - missing.length;
      entry.surfaces.skills = {
        supported: true,
        dir: def.skillsDir,
        total: present.size,
        canonicalCovered: covered,
        canonicalTotal: canonical.size,
        parityPct: Math.round((covered / canonical.size) * 1000) / 10,
        missing,
        extra,
        dangling: danglingSymlinks(def.skillsDir),
      };
    } else {
      entry.surfaces.skills = { supported: true, dir: def.skillsDir, present: false };
    }
  } else {
    entry.surfaces.skills = { supported: false, reason: "no skills directory in this harness" };
  }

  // --- mcp + hooks + features surface ---
  if (def.settings?.kind === "json") {
    const cfg = readJson(def.settings.path);
    const mcp = cfg && def.settings.mcpKey ? Object.keys(cfg[def.settings.mcpKey] || {}) : [];
    entry.surfaces.mcp = { supported: !!def.settings.mcpKey, configured: mcp.sort(), count: mcp.length };
    if (def.settings.hooksKey && cfg) {
      const events = Object.keys(cfg[def.settings.hooksKey] || {});
      entry.surfaces.hooks = { supported: true, events: events.sort(), count: events.length };
    }
    if (cfg?.env) entry.surfaces.env = { supported: true, count: Object.keys(cfg.env).length };
  } else if (def.settings?.kind === "toml") {
    const t = probeToml(def.settings.path);
    entry.surfaces.mcp = { supported: true, configured: t?.mcp || [], count: t?.mcp?.length || 0 };
    if (t?.features) entry.surfaces.features = t.features;
  }

  // --- codex hooks (separate file) ---
  if (def.hooksFile?.kind === "json") {
    const hk = readJson(def.hooksFile.path);
    const events = hk ? Object.keys(hk).filter((k) => k !== "state") : [];
    entry.surfaces.hooks = { supported: true, events: events.sort(), count: events.length };
  }

  // --- commands + agents ---
  entry.surfaces.commands = def.commandsDir
    ? { supported: true, count: countDir(def.commandsDir, ".md") ?? 0 }
    : { supported: false };
  entry.surfaces.agents = def.agentsDir
    ? { supported: true, count: countDir(def.agentsDir) ?? 0 }
    : { supported: false };

  report.harnesses[key] = entry;
}

// ---- output ---------------------------------------------------------------
if (process.argv.includes("--json")) {
  console.log(JSON.stringify(report, null, 2));
  process.exit(0);
}

const pad = (s, n) => String(s).padEnd(n);
const cell = (v) => (v === undefined || v === null ? "—" : v);

console.log(`\n  Cross-harness parity scorecard`);
console.log(`  canonical skills SoT: ${CANONICAL_SKILLS} (${canonical.size} skills)\n`);

console.log(
  "  " +
    pad("harness", 20) +
    pad("skills", 22) +
    pad("mcp", 8) +
    pad("hooks", 8) +
    pad("cmds", 7) +
    pad("agents", 7),
);
console.log("  " + "-".repeat(70));
for (const [, e] of Object.entries(report.harnesses)) {
  const s = e.surfaces.skills;
  const skillsCell = !s.supported
    ? "N/A (no dir)"
    : s.present === false
      ? "dir missing"
      : `${s.canonicalCovered}/${s.canonicalTotal} (${s.parityPct}%)${s.extra?.length ? ` +${s.extra.length}` : ""}`;
  console.log(
    "  " +
      pad(e.label, 20) +
      pad(skillsCell, 22) +
      pad(e.surfaces.mcp?.supported ? cell(e.surfaces.mcp.count) : "N/A", 8) +
      pad(e.surfaces.hooks?.supported ? cell(e.surfaces.hooks.count) : "N/A", 8) +
      pad(e.surfaces.commands?.supported ? cell(e.surfaces.commands.count) : "N/A", 7) +
      pad(e.surfaces.agents?.supported ? cell(e.surfaces.agents.count) : "N/A", 7),
  );
}

console.log("\n  Skill drift vs canonical:");
for (const [, e] of Object.entries(report.harnesses)) {
  const s = e.surfaces.skills;
  if (!s.supported || s.present === false) continue;
  const bits = [];
  if (s.missing?.length) bits.push(`${s.missing.length} missing`);
  if (s.extra?.length) bits.push(`${s.extra.length} extra/local`);
  if (s.dangling?.length) bits.push(`${s.dangling.length} DANGLING`);
  console.log(`  • ${pad(e.label, 18)} ${bits.length ? bits.join(", ") : "in sync"}`);
  if (s.missing?.length) console.log(`      missing: ${s.missing.join(", ")}`);
  if (s.dangling?.length) console.log(`      dangling: ${s.dangling.join(", ")}`);
}
console.log("");

