#!/usr/bin/env node
// harness-parity-scan — read-only cross-harness parity probe + gate.
//
// Measures how much of Luke's Pi-defined capability surface (skills, MCP tools,
// hooks, commands, agents) is present in each target harness — Claude Code CLI,
// Claude Desktop, Codex CLI/app, and Pi — against the canonical source of truth,
// and (in --gate mode) fails when a harness drifts below its declared target.
//
// Tiers (see docs/goals/goal-cross-harness-parity.md §0):
//   T1 Portable   — skills (markdown). Driven to full coverage on skills-capable
//                   harnesses (CC, Codex, Pi). Claude Desktop has no skills dir.
//   T2 Adaptable  — Pi tools exposed as MCP servers (the universal seam; the only
//                   surface that reaches Claude Desktop).
//   T3 Pi-native  — runtime behavior fused to Pi/claude-bridge. Tracked in the
//                   equivalence map (docs/pi-setup/harness-equivalence.md), never
//                   ported, so NOT gated numerically here.
//
// Safe by construction: reads files only, no model/API calls, mutates nothing.
// CI-safe: a harness whose dirs/config are absent on this machine is reported
// "not installed" and never fails the gate.
//
// Modes:  (default) human table | --json scorecard | --md drift report | --gate
//
// A "skill" = a directory containing SKILL.md. Scaffold/category dirs without
// SKILL.md are not skills and are not counted.

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const HOME = os.homedir();
const h = (...p) => path.join(HOME, ...p);

// ---- canonical source of truth -------------------------------------------
const CANONICAL_SKILLS = h("Projects/personal/skills");

// ---- parity contract (targets + honest exclusions) ------------------------
// A canonical skill absent from a harness is EITHER listed here with a reason
// (gate passes) OR an unexplained gap (gate fails). No silent coverage holes.
const PARITY = {
  // harnesses whose skills dir is driven to full canonical coverage
  t1Harnesses: ["claudeCode", "codex", "pi"],
  // canonical skill -> reason it's intentionally absent from <harness>
  skillExclusions: {
    claudeCode: {},
    codex: {},
    pi: {},
  },
  // T2: MCP server(s) that must be present in each MCP-capable harness.
  // Empty until the CHP MCP server (Phase 3) ships; gate ignores when empty.
  requiredMcp: {}, // e.g. { chp: ["claudeCode", "codex", "claudeDesktop"] }
};

// ---- harness definitions --------------------------------------------------
const HARNESSES = {
  pi: {
    label: "Pi (pi-mono-fork)",
    skillsDir: h(".pi/agent/skills"),
    settings: { kind: "json", path: h(".pi/agent/settings.json"), mcpKey: null },
    commandsDir: null,
    agentsDir: null,
    note: "Source harness. Native tools via extensions; skills auto-discovered.",
  },
  claudeCode: {
    label: "Claude Code CLI",
    skillsDir: h(".claude/skills"),
    settings: { kind: "json", path: h(".claude/settings.json"), mcpKey: "mcpServers", hooksKey: "hooks" },
    commandsDir: h(".claude/commands"),
    agentsDir: h(".claude/agents"),
    note: "Full surface: skills + MCP + hooks + commands + agents + env.",
  },
  codex: {
    label: "Codex CLI/app",
    skillsDir: h(".codex/skills"),
    settings: { kind: "toml", path: h(".codex/config.toml") },
    hooksFile: { kind: "json", path: h(".codex/hooks.json") },
    commandsDir: null,
    agentsDir: h(".codex/agents"),
    note: "Skills + MCP + hooks + plugins + native memories/goals/websearch.",
  },
  claudeDesktop: {
    label: "Claude Desktop",
    skillsDir: null, // NO skills dir — MCP is its only extensibility surface
    settings: {
      kind: "json",
      path: h("Library/Application Support/Claude/claude_desktop_config.json"),
      mcpKey: "mcpServers",
    },
    commandsDir: null,
    agentsDir: null,
    note: "MCP servers ONLY. No skills/hooks/commands (T2 ceiling).",
  },
};

// ---- helpers --------------------------------------------------------------
// A skill = a directory (following symlinks) that contains SKILL.md.
function listSkillDirs(dir) {
  if (!dir || !fs.existsSync(dir)) return null;
  const out = new Set();
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith(".")) continue;
    const full = path.join(dir, entry.name);
    try {
      const st = fs.statSync(full); // follows symlinks; throws on dangling
      if (st.isDirectory() && fs.existsSync(path.join(full, "SKILL.md"))) out.add(entry.name);
    } catch {
      /* dangling symlink or unreadable — not a loadable skill */
    }
  }
  return out;
}

function danglingSymlinks(dir) {
  if (!dir || !fs.existsSync(dir)) return [];
  const bad = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isSymbolicLink()) continue;
    try {
      fs.statSync(path.join(dir, entry.name));
    } catch {
      bad.push(entry.name);
    }
  }
  return bad;
}

function readJson(p) {
  try {
    return JSON.parse(fs.readFileSync(p, "utf8"));
  } catch {
    return null;
  }
}

// Light TOML probe — counts top-level [mcp_servers.<name>] tables and [features]
// booleans without a TOML dependency. Not a full parser.
function probeToml(p) {
  let text;
  try {
    text = fs.readFileSync(p, "utf8");
  } catch {
    return null;
  }
  const mcp = new Set();
  for (const m of text.matchAll(/^\[mcp_servers\.([A-Za-z0-9_-]+)\]\s*$/gm)) mcp.add(m[1]);
  const features = {};
  const fs2 = text.match(/^\[features\]([\s\S]*?)(?=^\[)/m);
  if (fs2) for (const m of fs2[1].matchAll(/^([A-Za-z0-9_]+)\s*=\s*(true|false)/gm)) features[m[1]] = m[2] === "true";
  return { mcp: [...mcp].sort(), features };
}

function countDir(dir, ext) {
  if (!dir || !fs.existsSync(dir)) return null;
  return fs.readdirSync(dir).filter((f) => !f.startsWith(".") && (!ext || f.endsWith(ext))).length;
}

// ---- scan -----------------------------------------------------------------
const canonical = listSkillDirs(CANONICAL_SKILLS);
if (!canonical) {
  console.error(`FATAL: canonical skills SoT not found at ${CANONICAL_SKILLS}`);
  process.exit(2);
}

const report = {
  schemaVersion: 2,
  source: "harness-parity-scan",
  safety: { modelCalls: false, apiCalls: false, mutates: false },
  canonicalSkills: { path: CANONICAL_SKILLS, count: canonical.size },
  tiers: { T1: "skills (portable)", T2: "MCP tools (adaptable)", T3: "Pi-native (equivalence map)" },
  harnesses: {},
};

for (const [key, def] of Object.entries(HARNESSES)) {
  const entry = { label: def.label, note: def.note, installed: true, surfaces: {} };

  // --- T1: skills ---
  if (def.skillsDir) {
    const present = listSkillDirs(def.skillsDir);
    if (present) {
      const exclusions = PARITY.skillExclusions[key] || {};
      const missingAll = [...canonical].filter((s) => !present.has(s)).sort();
      const missing = missingAll.filter((s) => !(s in exclusions));
      const excluded = missingAll.filter((s) => s in exclusions);
      const extra = [...present].filter((s) => !canonical.has(s)).sort();
      const covered = canonical.size - missingAll.length;
      entry.surfaces.skills = {
        tier: "T1",
        supported: true,
        dir: def.skillsDir,
        total: present.size,
        canonicalCovered: covered,
        canonicalTotal: canonical.size,
        parityPct: Math.round((covered / canonical.size) * 1000) / 10,
        missing, // unexplained — these fail the gate
        excluded, // intentionally absent (reasoned)
        extra, // harness-local, not in SoT
        dangling: danglingSymlinks(def.skillsDir),
      };
    } else {
      entry.installed = false;
      entry.surfaces.skills = { tier: "T1", supported: true, dir: def.skillsDir, present: false };
    }
  } else {
    entry.surfaces.skills = { tier: "T1", supported: false, reason: "no skills directory in this harness" };
  }

  // --- T2: MCP (+ hooks/env/features from settings) ---
  if (def.settings?.kind === "json") {
    const cfg = readJson(def.settings.path);
    if (!cfg && def.skillsDir === null && key === "claudeDesktop") entry.installed = !!cfg;
    const mcp = cfg && def.settings.mcpKey ? Object.keys(cfg[def.settings.mcpKey] || {}) : [];
    entry.surfaces.mcp = { tier: "T2", supported: !!def.settings.mcpKey, configured: mcp.sort(), count: mcp.length };
    if (def.settings.hooksKey && cfg) entry.surfaces.hooks = { tier: "T3", supported: true, events: Object.keys(cfg[def.settings.hooksKey] || {}).sort() };
    if (cfg?.env) entry.surfaces.env = { tier: "T3", supported: true, count: Object.keys(cfg.env).length };
  } else if (def.settings?.kind === "toml") {
    const t = probeToml(def.settings.path);
    entry.surfaces.mcp = { tier: "T2", supported: true, configured: t?.mcp || [], count: t?.mcp?.length || 0 };
    if (t?.features) entry.surfaces.features = t.features;
  }

  // --- Codex hooks (separate file; events nested under `hooks`) ---
  if (def.hooksFile?.kind === "json") {
    const hk = readJson(def.hooksFile.path);
    const eventsObj = hk?.hooks ?? hk ?? {};
    entry.surfaces.hooks = { tier: "T3", supported: true, events: Object.keys(eventsObj).filter((k) => k !== "state").sort() };
  }

  // --- commands + agents ---
  entry.surfaces.commands = def.commandsDir ? { tier: "T3", supported: true, count: countDir(def.commandsDir, ".md") ?? 0 } : { tier: "T3", supported: false };
  entry.surfaces.agents = def.agentsDir ? { tier: "T3", supported: true, count: countDir(def.agentsDir) ?? 0 } : { tier: "T3", supported: false };

  report.harnesses[key] = entry;
}

// ---- gate evaluation ------------------------------------------------------
function evaluateGate() {
  const failures = [];
  for (const key of PARITY.t1Harnesses) {
    const e = report.harnesses[key];
    const s = e?.surfaces?.skills;
    if (!s?.supported) continue;
    if (s.present === false) continue; // not installed on this machine — skip
    if (s.missing?.length) failures.push(`${e.label}: ${s.missing.length} unexplained missing skill(s): ${s.missing.join(", ")}`);
    if (s.dangling?.length) failures.push(`${e.label}: ${s.dangling.length} dangling skill symlink(s): ${s.dangling.join(", ")}`);
  }
  for (const [server, harnesses] of Object.entries(PARITY.requiredMcp)) {
    for (const key of harnesses) {
      const e = report.harnesses[key];
      const mcp = e?.surfaces?.mcp;
      if (!mcp?.supported) continue;
      if (e.installed === false) continue;
      if (!mcp.configured.includes(server)) failures.push(`${e.label}: required MCP server '${server}' not configured`);
    }
  }
  return failures;
}

// ---- renderers ------------------------------------------------------------
const pad = (s, n) => String(s).padEnd(n);

function humanTable() {
  let o = `\n  Cross-harness parity scorecard\n  canonical skills SoT: ${CANONICAL_SKILLS} (${canonical.size} skills)\n\n`;
  o += "  " + pad("harness", 20) + pad("skills (T1)", 22) + pad("mcp", 8) + pad("hooks", 8) + pad("cmds", 7) + pad("agents", 7) + "\n";
  o += "  " + "-".repeat(70) + "\n";
  for (const e of Object.values(report.harnesses)) {
    const s = e.surfaces.skills;
    const skillsCell = !s.supported ? "N/A (no dir)" : s.present === false ? "not installed" : `${s.canonicalCovered}/${s.canonicalTotal} (${s.parityPct}%)${s.extra?.length ? ` +${s.extra.length}` : ""}`;
    o += "  " + pad(e.label, 20) + pad(skillsCell, 22) +
      pad(e.surfaces.mcp?.supported ? e.surfaces.mcp.count : "N/A", 8) +
      pad(e.surfaces.hooks?.supported ? e.surfaces.hooks.events.length : "N/A", 8) +
      pad(e.surfaces.commands?.supported ? e.surfaces.commands.count : "N/A", 7) +
      pad(e.surfaces.agents?.supported ? e.surfaces.agents.count : "N/A", 7) + "\n";
  }
  o += "\n  Skill drift vs canonical:\n";
  for (const e of Object.values(report.harnesses)) {
    const s = e.surfaces.skills;
    if (!s.supported || s.present === false) continue;
    const bits = [];
    if (s.missing?.length) bits.push(`${s.missing.length} MISSING`);
    if (s.excluded?.length) bits.push(`${s.excluded.length} excluded`);
    if (s.extra?.length) bits.push(`${s.extra.length} extra/local`);
    if (s.dangling?.length) bits.push(`${s.dangling.length} DANGLING`);
    o += `  • ${pad(e.label, 18)} ${bits.length ? bits.join(", ") : "in sync ✓"}\n`;
    if (s.missing?.length) o += `      missing: ${s.missing.join(", ")}\n`;
    if (s.dangling?.length) o += `      dangling: ${s.dangling.join(", ")}\n`;
  }
  return o + "\n";
}

function markdownReport() {
  let o = `<!-- generated by scripts/harness-parity-scan.mjs --md — do not hand-edit -->\n`;
  o += `# Cross-harness parity (generated)\n\n`;
  o += `Canonical skills SoT: \`${CANONICAL_SKILLS}\` — ${canonical.size} skills (dirs with SKILL.md).\n\n`;
  o += `| Harness | Skills (T1) | MCP (T2) | Hooks | Cmds | Agents |\n|---|---|---|---|---|---|\n`;
  for (const e of Object.values(report.harnesses)) {
    const s = e.surfaces.skills;
    const sc = !s.supported ? "N/A — no skills dir" : s.present === false ? "not installed" : `${s.canonicalCovered}/${s.canonicalTotal} (${s.parityPct}%)${s.extra?.length ? ` +${s.extra.length} local` : ""}`;
    o += `| ${e.label} | ${sc} | ${e.surfaces.mcp?.supported ? e.surfaces.mcp.count : "N/A"} | ${e.surfaces.hooks?.supported ? e.surfaces.hooks.events.length : "N/A"} | ${e.surfaces.commands?.supported ? e.surfaces.commands.count : "N/A"} | ${e.surfaces.agents?.supported ? e.surfaces.agents.count : "N/A"} |\n`;
  }
  const failures = evaluateGate();
  o += `\n**Gate:** ${failures.length ? "❌ FAIL" : "✅ PASS"}\n`;
  if (failures.length) for (const f of failures) o += `- ${f}\n`;
  o += `\nTiers: T1 skills (portable, driven to full coverage) · T2 MCP tools (adaptable, the only surface reaching Claude Desktop) · T3 Pi-native (equivalence map, not gated). See \`docs/goals/goal-cross-harness-parity.md\` and \`docs/pi-setup/harness-equivalence.md\`.\n`;
  return o;
}

// ---- dispatch -------------------------------------------------------------
if (process.argv.includes("--json")) {
  console.log(JSON.stringify({ ...report, gate: { failures: evaluateGate() } }, null, 2));
  process.exit(0);
}
if (process.argv.includes("--md")) {
  process.stdout.write(markdownReport());
  process.exit(0);
}
if (process.argv.includes("--gate")) {
  const failures = evaluateGate();
  if (failures.length) {
    console.error("✗ harness-parity gate FAILED:");
    for (const f of failures) console.error(`  - ${f}`);
    process.exit(1);
  }
  console.log("✓ harness-parity gate passed");
