1	#!/usr/bin/env node
2	/**
3	 * skills-mcp — minimal stdio MCP server exposing a git skills dir as tools, for
4	 * registration on executor.sh (`executor call executor mcp addServer`). No deps:
5	 * hand-rolled JSON-RPC 2.0 over stdin/stdout (newline-delimited), enough for the
6	 * MCP initialize / tools/list / tools/call handshake.
7	 *
8	 * Tools: skills_list, skills_get { name }, skills_file_get { name, path }.
9	 * Backed by EXECUTOR_SKILLS_ROOT (default ~/Projects/personal/skills).
10	 * Run standalone for a smoke: `node skills-mcp.mjs --smoke`.
11	 */
12	import { list, get, fileGet } from "./executor-skills-source.mjs";
13	
14	const TOOLS = [
15	  { name: "skills_list", description: "List skills (name, version, description).",
16	    inputSchema: { type: "object", properties: {} } },
17	  { name: "skills_get", description: "Get a skill body + bundled file list.",
18	    inputSchema: { type: "object", properties: { name: { type: "string" } }, required: ["name"] } },
19	  { name: "skills_file_get", description: "Get one bundled file's content.",
20	    inputSchema: { type: "object", properties: { name: { type: "string" }, path: { type: "string" } }, required: ["name", "path"] } },
21	];
22	
23	function dispatch(name, args) {
24	  if (name === "skills_list") return { skills: list() };
25	  if (name === "skills_get") return get(args);
26	  if (name === "skills_file_get") return fileGet(args);
27	  throw new Error("unknown tool: " + name);
28	}
29	
30	function handle(msg) {
