#!/usr/bin/env node
/**
 * skills-mcp — minimal stdio MCP server exposing a git skills dir as tools, for
 * registration on executor.sh (`executor call executor mcp addServer`). No deps:
 * hand-rolled JSON-RPC 2.0 over stdin/stdout (newline-delimited), enough for the
 * MCP initialize / tools/list / tools/call handshake.
 *
 * Tools: skills_list, skills_get { name }, skills_file_get { name, path }.
 * Backed by EXECUTOR_SKILLS_ROOT (default ~/Projects/personal/skills).
 * Run standalone for a smoke: `node skills-mcp.mjs --smoke`.
 */
import { list, get, fileGet } from "./executor-skills-source.mjs";

const TOOLS = [
  { name: "skills_list", description: "List skills (name, version, description).",
    inputSchema: { type: "object", properties: {} } },
  { name: "skills_get", description: "Get a skill body + bundled file list.",
    inputSchema: { type: "object", properties: { name: { type: "string" } }, required: ["name"] } },
  { name: "skills_file_get", description: "Get one bundled file's content.",
    inputSchema: { type: "object", properties: { name: { type: "string" }, path: { type: "string" } }, required: ["name", "path"] } },
];

function dispatch(name, args) {
  if (name === "skills_list") return { skills: list() };
  if (name === "skills_get") return get(args);
  if (name === "skills_file_get") return fileGet(args);
  throw new Error("unknown tool: " + name);
}

function handle(msg) {
  const { id, method, params } = msg;
  if (method === "initialize")
    return { jsonrpc: "2.0", id, result: { protocolVersion: params?.protocolVersion ?? "2024-11-05",
      capabilities: { tools: {} }, serverInfo: { name: "skills", version: "0.1.0" } } };
  if (method === "notifications/initialized") return null; // notification, no reply
  if (method === "tools/list") return { jsonrpc: "2.0", id, result: { tools: TOOLS } };
  if (method === "tools/call") {
    try {
      const out = dispatch(params.name, params.arguments ?? {});
      return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text: JSON.stringify(out) }] } };
    } catch (e) {
      return { jsonrpc: "2.0", id, result: { isError: true, content: [{ type: "text", text: String(e.message) }] } };
    }
  }
  if (id !== undefined) return { jsonrpc: "2.0", id, error: { code: -32601, message: "method not found: " + method } };
  return null;
}

if (process.argv.includes("--smoke")) {
  // exercise the handlers without stdio
  const init = handle({ jsonrpc: "2.0", id: 1, method: "initialize", params: {} });
  const tools = handle({ jsonrpc: "2.0", id: 2, method: "tools/list" });
  const listed = handle({ jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "skills_list", arguments: {} } });
  const skills = JSON.parse(listed.result.content[0].text).skills;
  if (!init.result.serverInfo || tools.result.tools.length !== 3 || !Array.isArray(skills))
    throw new Error("FAIL smoke");
  console.log(`ok — skills-mcp smoke: ${tools.result.tools.length} tools, ${skills.length} skills exposed`);
  process.exit(0);
}

// HTTP (streamable-http) mode: `node skills-mcp.mjs --http 8765`
const httpFlag = process.argv.indexOf("--http");
if (httpFlag !== -1) {
  const port = Number(process.argv[httpFlag + 1] ?? 8765);
  const { createServer } = await import("node:http");
  const srv = createServer((req, res) => {
    if (req.method === "GET") { res.writeHead(200, { "content-type": "text/event-stream" }); res.end(); return; }
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      let reply;
      try { reply = handle(JSON.parse(body)); } catch { res.writeHead(400).end(); return; }
      res.writeHead(200, { "content-type": "application/json" });
      res.end(reply ? JSON.stringify(reply) : "");
    });
  });
  srv.listen(port, "127.0.0.1", () => console.log(`skills-mcp http on http://127.0.0.1:${port}/`));
} else {
// stdio JSON-RPC loop (newline-delimited)
let buf = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  buf += chunk;
  let nl;
  while ((nl = buf.indexOf("\n")) !== -1) {
    const line = buf.slice(0, nl).trim();
    buf = buf.slice(nl + 1);
    if (!line) continue;
    let reply;
    try { reply = handle(JSON.parse(line)); } catch { continue; }
    if (reply) process.stdout.write(JSON.stringify(reply) + "\n");
  }
});
}

