/**
 * executor-skills-source — the custom source you register ON executor.sh
 * (Add Source → custom JS) to turn a git skills directory into a shared,
 * versioned skill store exposed to every runtime through the executor gateway.
 *
 * executor.sh (github.com/RhysSullivan/executor) normalizes custom JS functions
 * into tools with input/output schemas, handles auth/policies, and shares the
 * catalog across the team + every MCP-compatible agent (Pi, Claude Code, Cursor,
 * Codex) pointed at the local gateway (http://127.0.0.1:4788). Self-hosted — no
 * SaaS dependency.
 *
 * Source of truth = a git checkout of skills (e.g. ~/Projects/personal/skills).
 * Versioning is free: per-skill `version` = short content hash of body+files (changes
 * iff the skill changes), so the diff-cache engine pulls only what moved. (Swap to
 * `git log -1 --format=%h -- <dir>` if commit-pinned versions are preferred.)
 *
 * GROUND TRUTH (executor v1.5.10): executor has NO raw "custom JS" source type —
 * CLI source types are openapi | graphql | mcp | onepassword | coreTools. So these
 * three functions are wrapped in a minimal **MCP server** (tools skills.list/get/
 * fileGet) and registered with:
 *   executor call executor mcp addServer '{"name":"skills","command":"node","args":["<this-dir>/skills-mcp.mjs"]}'
 * Runtimes then reach the tools through the gateway via `executor mcp` in mcp.json.
 * (The MCP-server shim is the small remaining build step; logic below is unchanged.)
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const SKILLS_ROOT = process.env.EXECUTOR_SKILLS_ROOT
  || join(process.env.HOME, "Projects/personal/skills");

const sha = (buf) => createHash("sha256").update(buf).digest("hex").slice(0, 16);

function walk(dir, base = dir) {
  return readdirSync(dir).flatMap((e) => {
    const full = join(dir, e);
    let st; try { st = statSync(full); } catch { return []; } // skip broken symlinks
    return st.isDirectory() ? walk(full, base) : [relative(base, full)];
  });
}
function skillDirs() {
  return readdirSync(SKILLS_ROOT)
    .filter((n) => existsSync(join(SKILLS_ROOT, n, "SKILL.md")))
    .sort();
}
function skillVersion(name) {
  const dir = join(SKILLS_ROOT, name);
  const parts = walk(dir).sort().map((p) => p + ":" + sha(readFileSync(join(dir, p))));
  return sha(parts.join("\n")); // content hash over all files = version
}

/** tool: skills.list -> [{ name, version, description }] (cheap; no bodies) */
export function list() {
  return skillDirs().map((name) => {
    const body = readFileSync(join(SKILLS_ROOT, name, "SKILL.md"), "utf8");
    const desc = body.match(/^description:\s*(.+)$/m)?.[1]?.replace(/^["']|["']$/g, "") ?? "";
    return { name, version: skillVersion(name), description: desc };
  });
}

/** tool: skills.get { name } -> { name, version, body, files:[{path}] } (file list, not contents) */
export function get({ name }) {
  const dir = join(SKILLS_ROOT, name);
  const files = walk(dir).filter((p) => p !== "SKILL.md").map((path) => ({ path }));
  return { name, version: skillVersion(name), body: readFileSync(join(dir, "SKILL.md"), "utf8"), files };
}

/** tool: skills.fileGet { name, path } -> { content } (one bundled file on demand) */
export function fileGet({ name, path }) {
  return { content: readFileSync(join(SKILLS_ROOT, name, path), "utf8") };
}

