#!/usr/bin/env node
/**
 * chp-mcp-server — the Cross-Harness Parity (CHP) MCP server.
 *
 * Exposes the canonical skill library (~/Projects/personal/skills, override via
 * CHP_SKILLS_ROOT) as MCP tools so EVERY harness can reach it — including Claude
 * Desktop, which has no skills directory and whose only extensibility surface is
 * MCP. This is the T2 seam from docs/goals/goal-cross-harness-parity.md: it lifts
 * the T1 skill asset over the one wall (Desktop) that T1 can't cross.
 *
 * Zero dependencies: hand-rolled JSON-RPC 2.0 over stdin/stdout (newline-delimited
 * — MCP's stdio framing), enough for the initialize / tools/list / tools/call
 * handshake. Modelled on prototypes/skill-sync/skills-mcp.mjs.
 *
 * Tools:
 *   list_skills            -> [{ name, description }]      (catalog, no bodies)
 *   read_skill { name }    -> the full SKILL.md text       (the instructions)
 *   read_skill_file { name, path } -> one bundled file's text (refs, scripts)
 *
 * Read-only. No network, no secrets, no writes, no child processes. Path-traversal
 * guarded: every read is confined to a single skill dir under the skills root.
 *
 * Smoke (no stdio):           node chp-mcp-server.mjs --smoke
 * stdio server (default):     node chp-mcp-server.mjs
 */
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, resolve, isAbsolute } from "node:path";
import { homedir } from "node:os";

const SKILLS_ROOT = process.env.CHP_SKILLS_ROOT
  || join(homedir(), "Projects/personal/skills");
const SERVER = { name: "pi-parity", version: "0.1.0" };

// ---- skill library (canonical SoT) ----------------------------------------
// A skill = a directory containing SKILL.md (matches harness-parity-scan.mjs).
function skillDirs() {
  if (!existsSync(SKILLS_ROOT)) return [];
  return readdirSync(SKILLS_ROOT)
    .filter((n) => !n.startsWith(".") && existsSync(join(SKILLS_ROOT, n, "SKILL.md")))
    .sort();
}

// Resolve a name to its skill dir, refusing anything that escapes the root.
function skillDir(name) {
  if (!name || typeof name !== "string" || name.includes("/") || name.includes("\\") || name === "." || name === "..")
    throw new Error(`invalid skill name: ${name}`);
  const dir = join(SKILLS_ROOT, name);
  if (!existsSync(join(dir, "SKILL.md"))) throw new Error(`no such skill: ${name}`);
  return dir;
}

// Confine a bundled-file path to the skill dir (no .. escape, no absolute paths).
function safeJoin(dir, p) {
  if (!p || typeof p !== "string" || isAbsolute(p)) throw new Error(`invalid path: ${p}`);
  const full = resolve(dir, p);
  const rel = relative(dir, full);
  if (rel.startsWith("..") || isAbsolute(rel)) throw new Error(`path escapes skill dir: ${p}`);
  return full;
}

function listSkills() {
  return skillDirs().map((name) => {
    const body = readFileSync(join(SKILLS_ROOT, name, "SKILL.md"), "utf8");
    const desc = body.match(/^description:\s*(.+)$/m)?.[1]?.replace(/^["']|["']$/g, "") ?? "";
    return { name, description: desc };
  });
}
function readSkill({ name }) {
  return readFileSync(join(skillDir(name), "SKILL.md"), "utf8"); // raw markdown
}
function readSkillFile({ name, path }) {
  const dir = skillDir(name);
  const full = safeJoin(dir, path);
  const st = statSync(full);
  if (!st.isFile()) throw new Error(`not a file: ${path}`);
  return readFileSync(full, "utf8");
}

// ---- MCP tool registry + dispatch -----------------------------------------
const TOOLS = [
  { name: "list_skills", description: "List all skills in the canonical library (name + description). No bodies.",
    inputSchema: { type: "object", properties: {} } },
  { name: "read_skill", description: "Get the full SKILL.md instructions for one skill by name.",
    inputSchema: { type: "object", properties: { name: { type: "string" } }, required: ["name"] } },
  { name: "read_skill_file", description: "Read one bundled file inside a skill dir (e.g. references/foo.md).",
    inputSchema: { type: "object", properties: { name: { type: "string" }, path: { type: "string" } }, required: ["name", "path"] } },
];

// Returns a string (emitted as text verbatim) or an object (emitted as JSON text).
function dispatch(name, args) {
  if (name === "list_skills") return listSkills();
  if (name === "read_skill") return readSkill(args);
  if (name === "read_skill_file") return readSkillFile(args);
  throw new Error("unknown tool: " + name);
}

function handle(msg) {
  const { id, method, params } = msg;
  if (method === "initialize")
    return { jsonrpc: "2.0", id, result: { protocolVersion: params?.protocolVersion ?? "2024-11-05",
      capabilities: { tools: {} }, serverInfo: SERVER } };
  if (method === "notifications/initialized") return null; // notification, no reply
  if (method === "ping") return { jsonrpc: "2.0", id, result: {} };
  if (method === "tools/list") return { jsonrpc: "2.0", id, result: { tools: TOOLS } };
  if (method === "tools/call") {
    try {
      const out = dispatch(params.name, params.arguments ?? {});
      const text = typeof out === "string" ? out : JSON.stringify(out);
      return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text }] } };
    } catch (e) {
      return { jsonrpc: "2.0", id, result: { isError: true, content: [{ type: "text", text: String(e.message) }] } };
    }
  }
  if (id !== undefined) return { jsonrpc: "2.0", id, error: { code: -32601, message: "method not found: " + method } };
  return null;
}

// ---- smoke (exercise handlers without stdio) ------------------------------
if (process.argv.includes("--smoke")) {
  const init = handle({ jsonrpc: "2.0", id: 1, method: "initialize", params: {} });
  const tools = handle({ jsonrpc: "2.0", id: 2, method: "tools/list" });
  const listed = handle({ jsonrpc: "2.0", id: 3, method: "tools/call", params: { name: "list_skills", arguments: {} } });
  const skills = JSON.parse(listed.result.content[0].text);
  if (init.result.serverInfo?.name !== SERVER.name || tools.result.tools.length !== 3 || !Array.isArray(skills))
    throw new Error("FAIL smoke");
  // exercise read_skill on the first skill, and traversal guards
  if (skills.length) {
    const got = handle({ jsonrpc: "2.0", id: 4, method: "tools/call", params: { name: "read_skill", arguments: { name: skills[0].name } } });
    if (got.result.isError || !got.result.content[0].text.includes("name:")) throw new Error("FAIL read_skill");
  }
  const esc = handle({ jsonrpc: "2.0", id: 5, method: "tools/call", params: { name: "read_skill_file", arguments: { name: "../../etc", path: "passwd" } } });
  if (!esc.result.isError) throw new Error("FAIL traversal guard (name)");
  console.log(`ok — chp-mcp smoke: ${tools.result.tools.length} tools, ${skills.length} skills exposed, traversal guarded`);
  process.exit(0);
}

// ---- stdio JSON-RPC loop (newline-delimited) ------------------------------
let buf = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  buf += chunk;
  let nl;
  while ((nl = buf.indexOf("\n")) !== -1) {
    const line = buf.slice(0, nl).trim();
    buf = buf.slice(nl + 1);
    if (!line) continue;
    let reply;
    try { reply = handle(JSON.parse(line)); } catch { continue; }
    if (reply) process.stdout.write(JSON.stringify(reply) + "\n");
  }
});

