#!/usr/bin/env node
/**
 * deploy-chp-mcp — install the CHP MCP server to a STABLE path outside any git
 * worktree, so the three harness configs (CC / Codex / Claude Desktop) can point
 * at a location that survives worktree cleanup and branch churn.
 *
 * Canonical source: scripts/chp-mcp-server.mjs (version-controlled).
 * Deployed copy:    ~/.local/share/chp/chp-mcp-server.mjs (stable; what configs reference).
 *
 *   node scripts/deploy-chp-mcp.mjs          # copy source -> stable path, verify
 *   node scripts/deploy-chp-mcp.mjs --check  # verify deployed copy matches source (no write)
 *
 * --check is the no-drift ratchet: exit 1 if the deployed copy is missing or stale.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync, mkdirSync, chmodSync } from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { fileURLToPath } from "node:url";

const SRC = join(dirname(fileURLToPath(import.meta.url)), "chp-mcp-server.mjs");
const DEST_DIR = join(homedir(), ".local/share/chp");
const DEST = join(DEST_DIR, "chp-mcp-server.mjs");
const sha = (b) => createHash("sha256").update(b).digest("hex");

if (!existsSync(SRC)) {
  console.error(`FATAL: source not found at ${SRC}`);
  process.exit(2);
}
const srcBuf = readFileSync(SRC);
const check = process.argv.includes("--check");

if (check) {
  if (!existsSync(DEST)) {
    console.error(`✗ CHP MCP server not deployed (missing ${DEST}). Run: npm run parity:deploy-mcp`);
    process.exit(1);
  }
  if (sha(readFileSync(DEST)) !== sha(srcBuf)) {
    console.error(`✗ deployed CHP MCP server is STALE vs source. Run: npm run parity:deploy-mcp`);
    process.exit(1);
  }
  console.log(`✓ CHP MCP server deployed copy matches source (${DEST})`);
  process.exit(0);
}

mkdirSync(DEST_DIR, { recursive: true });
writeFileSync(DEST, srcBuf);
chmodSync(DEST, 0o755);
if (sha(readFileSync(DEST)) !== sha(srcBuf)) {
  console.error("FATAL: post-copy hash mismatch");
  process.exit(2);
}
console.log(`✓ deployed CHP MCP server -> ${DEST}`);
console.log(`  wire harnesses to:  node ${DEST}   (server name: pi-parity)`);

